insert into public.roots (slug, form, kind, meaning, origin, source_word, pronunciation, explanation) values
('bene', 'bene-', 'prefix', 'well, favorably', 'Latin', 'Latin bene (well)', NULL, 'This prefix carries the sense “well, favorably.” It appears in inherited and learned words about doing or wishing good.'),
('mal', 'mal-', 'prefix', 'badly, ill', 'Latin', 'Latin male (badly), malus (bad)', NULL, 'This prefix carries the sense “badly, ill.” Its shape varies with the Latin formation; not every English word beginning mal belongs here.'),
('vol', 'vol / volunt', 'root', 'wish, will', 'Latin', 'Latin velle (to wish), volo (I wish), voluntas (will)', NULL, 'This root carries the sense “wish, will.” The changing stems reflect Latin forms rather than interchangeable English word parts.'),
('loqu', 'loqu / locut', 'root', 'speak', 'Latin', 'Latin loqui (to speak), locutus (having spoken)', NULL, 'This root carries the sense “speak.” The locut form comes from the participial stem of the same verb.'),
('cred', 'cred', 'root', 'believe, trust', 'Latin', 'Latin credere (to believe)', NULL, 'This root carries the sense “believe, trust.” It underlies words about belief, credibility, and accepting statements as true.'),
('plac', 'plac', 'root', 'please, calm', 'Latin', 'Latin placere (to please), placare (to soothe)', NULL, 'This root carries the sense “please, calm.” These related Latin verbs contribute either satisfaction or the calming of anger.'),
('voc', 'voc', 'root', 'voice, call', 'Latin', 'Latin vox, vocis (voice), vocare (to call)', NULL, 'This root carries the sense “voice, call.” It can refer to an actual voice or to calling something by a name.'),
('gno', 'gno / gnos', 'root', 'know', 'Greek', 'Greek gignoskein (to know), gnosis (knowledge)', NULL, 'This root carries the sense “know.” Latin cognoscere is historically related, but Latin cognizant is not segmented here as a Greek formation.'),
('path', 'path', 'root', 'feeling, suffering', 'Greek', 'Greek pathos (experience, suffering, feeling)', NULL, 'This root carries the sense “feeling, suffering.” English formations may emphasize emotion rather than bodily suffering.'),
('morph', 'morph', 'root', 'form, shape', 'Greek', 'Greek morphe (form)', NULL, 'This root carries the sense “form, shape.” It contributes the idea of a shape or a change in shape.'),
('chron', 'chron', 'root', 'time', 'Greek', 'Greek chronos (time)', NULL, 'This root carries the sense “time.” It appears in words about duration, historical timing, and sequence.'),
('phil', 'phil', 'root', 'loving, fond of', 'Greek', 'Greek philos (dear, loving)', NULL, 'This root carries the sense “loving, fond of.” In compounds it describes affection for the thing named by the other element.'),
('anthrop', 'anthrop', 'root', 'human being, humankind', 'Greek', 'Greek anthropos (human being)', NULL, 'This root carries the sense “human being, humankind.” It denotes people generally, not only adult males.'),
('mis', 'mis / miso', 'root', 'hate', 'Greek', 'Greek misein (to hate), misos (hatred)', NULL, 'This root carries the sense “hate.” This Greek element is distinct from the English prefix mis-, meaning wrongly or badly.'),
('dict', 'dict', 'root', 'say, declare', 'Latin', 'Latin dicere (to say), dictum (something said)', NULL, 'This root carries the sense “say, declare.” Its declarative sense extends from ordinary speech to formal pronouncements.'),
('ambi', 'ambi-', 'prefix', 'both, on both sides', 'Latin', 'Latin ambi- (around, on both sides)', NULL, 'This prefix carries the sense “both, on both sides.” Some descendants preserve the idea of two alternatives rather than physical sides.'),
('a-an', 'a- / an-', 'prefix', 'not, without', 'Greek', 'Greek privative a-, an- before vowels', NULL, 'This prefix carries the sense “not, without.” It marks absence or negation and should not be confused with unrelated a- prefixes.'),
('in-im', 'in- / im-', 'prefix', 'not', 'Latin', 'Latin negative in-', NULL, 'This prefix carries the sense “not.” The form im- occurs before certain labial consonants; other assimilated forms include il- and ir-.'),
('eu', 'eu-', 'prefix', 'well, good', 'Greek', 'Greek eu (well)', NULL, 'This prefix carries the sense “well, good.” It can suggest favorable wording or a desirable condition rather than moral goodness.'),
('log', 'log', 'root', 'speech, account', 'Greek', 'Greek logos (word, discourse, account)', NULL, 'This root carries the sense “speech, account.” Different formations emphasize speaking, explanation, or systematic study.'),
('curr-curs', 'curr / curs', 'root', 'run', 'Latin', 'Latin currere (to run), cursus (a running)', NULL, 'This root carries the sense “run.” Figurative developments include passing quickly and going ahead of something else.'),
('sequ', 'sequ / secut', 'root', 'follow', 'Latin', 'Latin sequi (to follow), secutus (having followed)', NULL, 'This root carries the sense “follow.” Some descendants concern compliance rather than following in physical space.'),
('fid', 'fid', 'root', 'trust, faith', 'Latin', 'Latin fides (faith), fidere (to trust)', NULL, 'This root carries the sense “trust, faith.” It contributes ideas of loyalty, confidence, and reliability.'),
('luc', 'luc', 'root', 'light', 'Latin', 'Latin lux, lucis (light), lucere (to shine)', NULL, 'This root carries the sense “light.” The figurative extension from light to mental clarity is especially important.'),
('pug', 'pug / pugn', 'root', 'fight', 'Latin', 'Latin pugnare (to fight), pugna (fight)', NULL, 'This root carries the sense “fight.” Some descendants concern verbal attacks or resistance rather than physical combat.'),
('ver', 'ver', 'root', 'true', 'Latin', 'Latin verus (true)', NULL, 'This root carries the sense “true.” Its descendants may describe actual truth or merely the appearance of truth.'),
('tac-tic', 'tac / tic', 'root', 'be silent', 'Latin', 'Latin tacere (to be silent)', NULL, 'This root carries the sense “be silent.” The tic form reflects a Latin vowel change in compounds, not a separate English root.'),
('greg', 'greg', 'root', 'flock, group', 'Latin', 'Latin grex, gregis (flock)', NULL, 'This root carries the sense “flock, group.” Its figurative descendants concern company, assembling, or standing apart from a group.'),
('ous', '-ous', 'suffix', 'having, characterized by', 'Latin via French', 'Latin -osus, with other Latin adjective endings converging in English -ous', NULL, 'This suffix carries the sense “having, characterized by.” It forms adjectives, but an English -ous ending does not always directly continue Latin -osus.'),
('ity', '-ity', 'suffix', 'state, quality', 'Latin via French', 'Latin -itas, -itatis', NULL, 'This suffix carries the sense “state, quality.” It commonly turns an adjectival concept into the name of a quality.'),
('ate', '-ate', 'suffix', 'make, act upon', 'Latin', 'Latin -atus, participial ending of verbs in -are', NULL, 'This suffix carries the sense “make, act upon.” English verbs often developed from Latin participles; this is not a detachable historical unit in every verb ending in -ate.'),
('ize', '-ize', 'suffix', 'make, render, engage in', 'Greek via Latin and French', 'Greek -izein, a verb-forming ending', NULL, 'This suffix carries the sense “make, render, engage in.” It forms verbs, often from nouns or adjectives, but its precise force depends on the base.'),
('ent-ant', '-ent / -ant', 'suffix', 'being, doing', 'Latin via French', 'Latin participial endings -ent-, -ant-', NULL, 'This suffix carries the sense “being, doing.” It forms many adjectives and some nouns, though not every apparent instance is a separable English suffix.'),
('ic', '-ic', 'suffix', 'of, relating to', 'Greek via Latin', 'Greek -ikos, Latin -icus', NULL, 'This suffix carries the sense “of, relating to.” It forms adjectives expressing a relation rather than a single fixed descriptive quality.'),
('anti', 'anti-', 'prefix', 'against, opposed to', 'Greek', 'Greek anti (against, opposite)', NULL, 'This prefix carries the sense “against, opposed to.” It marks opposition, but the meaning of a whole word can be more specialized than simple negation.');
insert into public.words (slug, word, pronunciation, part_of_speech, definition, secondary_meanings, plain_english, examples, synonyms, antonyms, difficulty, gre_frequency, etymology, etymology_status, memory_aid, confused_with, confused_note) values
('benevolent', 'benevolent', 'buh-NEV-uh-lunt', 'adjective', 'Wishing others well and inclined to help them.', ARRAY[]::text[], 'A benevolent person genuinely wants good things for others.', ARRAY['The benevolent trustee funded scholarships without seeking recognition.','Her benevolent intentions did not excuse the policy’s practical failures.'], ARRAY['kind','charitable','well-meaning'], ARRAY['malevolent','unkind'], 2, 3, 'From Latin benevolens, from bene (well) and velle (to wish).', 'established', NULL, ARRAY[]::text[], NULL),
('benefactor', 'benefactor', 'BEN-uh-fak-ter', 'noun', 'A person who provides help, especially financial support.', ARRAY[]::text[], 'A benefactor gives someone or something valuable support.', ARRAY['An anonymous benefactor paid for the laboratory’s renovation.','The museum refused to let its benefactor dictate the exhibition’s conclusions.'], ARRAY['patron','donor','supporter'], ARRAY[]::text[], 2, 3, 'From Latin benefactor (one who does good), combining bene (well) and a formation from facere (to do).', 'established', NULL, ARRAY[]::text[], NULL),
('beneficent', 'beneficent', 'buh-NEF-uh-sunt', 'adjective', 'Doing good or providing practical help.', ARRAY[]::text[], 'Someone beneficent actually helps rather than just wishing you well.', ARRAY['The foundation’s beneficent work restored clinics across the province.','Even beneficent reforms can produce unintended inequalities.'], ARRAY['charitable','generous','helpful'], ARRAY['harmful','malevolent'], 2, 3, 'From Latin beneficent-, the stem of beneficens (doing good), from bene (well) and facere (to do).', 'established', NULL, ARRAY[]::text[], NULL),
('benign', 'benign', 'bih-NINE', 'adjective', 'Gentle or harmless in character or effect.', ARRAY['Not cancerous.'], 'Something benign is not likely to hurt you.', ARRAY['The apparently benign regulation imposed substantial costs on small farms.','His benign manner encouraged witnesses to speak candidly.'], ARRAY['harmless','gentle','kindly'], ARRAY['malignant','harmful'], 2, 3, 'From Latin benignus (kindly), traditionally analyzed as bene (well) plus an element related to birth or kind.', 'established', NULL, ARRAY[]::text[], NULL),
('malevolent', 'malevolent', 'muh-LEV-uh-lunt', 'adjective', 'Wishing harm to others.', ARRAY[]::text[], 'A malevolent person wants someone else to suffer.', ARRAY['The anonymous letters revealed a malevolent desire to ruin her career.','The novel’s antagonist is calculating rather than impulsively malevolent.'], ARRAY['malicious','spiteful','hateful'], ARRAY['benevolent','kindly'], 2, 3, 'From Latin malevolens, from male (ill) and velle (to wish).', 'established', NULL, ARRAY[]::text[], NULL),
('malign', 'malign', 'muh-LINE', 'verb', 'To speak damagingly and unfairly about someone.', ARRAY['Harmful or malevolent, when used as an adjective.'], 'To malign someone is to attack their reputation unfairly.', ARRAY['The pamphlet maligned reformers as enemies of public order.','Critics should evaluate the findings rather than malign the researchers.'], ARRAY['slander','defame','vilify'], ARRAY['praise','commend'], 2, 3, 'Through French from Latin malignus (ill-disposed), from male (ill) and an element related to birth or kind.', 'established', NULL, ARRAY[]::text[], NULL),
('maleficent', 'maleficent', 'muh-LEF-ih-sunt', 'adjective', 'Causing harm or intending evil.', ARRAY[]::text[], 'Something maleficent does harm or aims to.', ARRAY['The legend attributes the drought to a maleficent spirit.','The tribunal examined the ruler’s maleficent use of state power.'], ARRAY['harmful','malevolent','malign'], ARRAY['beneficent','benevolent'], 3, 1, 'From Latin maleficent-, the stem of maleficens (doing evil), from male (ill) and facere (to do).', 'established', NULL, ARRAY[]::text[], NULL),
('volition', 'volition', 'voh-LISH-un', 'noun', 'The faculty or act of making a conscious choice.', ARRAY[]::text[], 'Volition means choosing something for yourself.', ARRAY['She joined the expedition of her own volition.','The experiment distinguished reflexive movement from action guided by volition.'], ARRAY['will','choice','intention'], ARRAY[]::text[], 2, 3, 'From French volition or Medieval Latin volitio, ultimately from Latin velle (to wish).', 'established', NULL, ARRAY[]::text[], NULL),
('loquacious', 'loquacious', 'loh-KWAY-shus', 'adjective', 'Inclined to talk at length.', ARRAY[]::text[], 'A loquacious person has a lot to say.', ARRAY['The usually loquacious senator answered the inquiry with unusual brevity.','A loquacious guide delayed the tour with elaborate anecdotes.'], ARRAY['talkative','garrulous','voluble'], ARRAY['taciturn','reticent'], 2, 3, 'From Latin loquax, loquacis (talkative), from loqui (to speak), with an English adjectival ending.', 'established', NULL, ARRAY[]::text[], NULL),
('eloquent', 'eloquent', 'EL-uh-kwunt', 'adjective', 'Expressing ideas fluently and persuasively.', ARRAY[]::text[], 'Someone eloquent makes a point clearly and powerfully.', ARRAY['Her eloquent defense persuaded even skeptical members of the committee.','The abandoned houses offered eloquent testimony to the town’s decline.'], ARRAY['articulate','expressive','persuasive'], ARRAY['inarticulate'], 2, 3, 'From Latin eloquens, the participle of eloqui (to speak out), from e- (out) and loqui (to speak).', 'established', NULL, ARRAY[]::text[], NULL),
('circumlocution', 'circumlocution', 'sur-kum-loh-KYOO-shun', 'noun', 'An indirect, unnecessarily wordy way of expressing something.', ARRAY[]::text[], 'Circumlocution is talking around a point instead of stating it.', ARRAY['The minister’s circumlocution obscured a straightforward refusal.','Legal precision does not require endless circumlocution.'], ARRAY['wordiness','periphrasis','verbosity'], ARRAY['directness','concision'], 2, 3, 'From Latin circumlocutio, from circum (around) and loqui (to speak), with the participial stem locut-.', 'established', NULL, ARRAY[]::text[], NULL),
('soliloquy', 'soliloquy', 'suh-LIL-uh-kwee', 'noun', 'A dramatic speech in which a character voices private thoughts aloud.', ARRAY[]::text[], 'In a soliloquy, a character lets the audience hear their private thoughts.', ARRAY['The final soliloquy exposes the ruler’s fear of betrayal.','Her soliloquy interrupts the action but deepens the tragedy.'], ARRAY['monologue','self-address'], ARRAY[]::text[], 2, 1, 'From Late Latin soliloquium, combining Latin solus (alone) and loqui (to speak).', 'established', NULL, ARRAY[]::text[], NULL),
('credulous', 'credulous', 'KREJ-uh-lus', 'adjective', 'Too ready to accept claims as true.', ARRAY[]::text[], 'A credulous person believes things without checking them.', ARRAY['The fraudulent investment appealed to credulous buyers.','Even experienced readers can be credulous when a story confirms their prejudices.'], ARRAY['gullible','trusting','naive'], ARRAY['skeptical','incredulous'], 2, 3, 'From Latin credulus (believing readily), from credere (to believe).', 'established', NULL, ARRAY['credible'], 'Credulous describes someone too ready to believe; credible describes something believable.'),
('incredulous', 'incredulous', 'in-KREJ-uh-lus', 'adjective', 'Unwilling or unable to believe something.', ARRAY[]::text[], 'If you are incredulous, you find a claim hard to believe.', ARRAY['The auditors were incredulous at the company’s explanation.','She gave an incredulous laugh when told the archive had no index.'], ARRAY['skeptical','disbelieving','doubtful'], ARRAY['credulous','trusting'], 2, 3, 'From Latin incredulus (unbelieving), from negative in- and credulus (believing readily).', 'established', NULL, ARRAY[]::text[], NULL),
('credence', 'credence', 'KREE-duns', 'noun', 'Belief in or acceptance of a claim as true.', ARRAY[]::text[], 'Giving a claim credence means taking it seriously as true.', ARRAY['The newly discovered letters lend credence to her interpretation.','The panel gave little credence to unsupported accusations.'], ARRAY['belief','acceptance','trust'], ARRAY['disbelief','skepticism'], 2, 3, 'Through French from Medieval Latin credentia, from Latin credere (to believe).', 'established', NULL, ARRAY[]::text[], NULL),
('placate', 'placate', 'PLAY-kayt', 'verb', 'To calm someone’s anger, often through concessions.', ARRAY[]::text[], 'You placate someone by doing something that makes them less angry.', ARRAY['The director offered refunds to placate dissatisfied subscribers.','A symbolic apology failed to placate the striking workers.'], ARRAY['appease','pacify','mollify'], ARRAY['provoke','antagonize'], 2, 3, 'From Latin placatus, the past participle of placare (to soothe).', 'established', NULL, ARRAY[]::text[], NULL),
('implacable', 'implacable', 'im-PLAK-uh-bul', 'adjective', 'Impossible to appease or soften.', ARRAY[]::text[], 'An implacable opponent will not be won over.', ARRAY['The prosecutor remained an implacable critic of the settlement.','Decades of negotiation had not diminished their implacable hostility.'], ARRAY['unappeasable','relentless','unyielding'], ARRAY['conciliatory','forgiving'], 2, 3, 'From Latin implacabilis, from negative in- and placabilis (able to be appeased), from placare.', 'established', NULL, ARRAY[]::text[], NULL),
('complacent', 'complacent', 'kum-PLAY-sunt', 'adjective', 'Self-satisfied and insufficiently alert to risks or faults.', ARRAY[]::text[], 'You are complacent when feeling comfortable makes you stop checking for problems.', ARRAY['Early success made the firm complacent about emerging competitors.','The report warns against becoming complacent after a single favorable result.'], ARRAY['smug','self-satisfied','uncritical'], ARRAY['vigilant','concerned'], 2, 3, 'From Latin complacens, participle of complacere (to please greatly), from com- and placere (to please).', 'established', NULL, ARRAY[]::text[], NULL),
('placid', 'placid', 'PLAS-id', 'adjective', 'Calm and not easily disturbed.', ARRAY[]::text[], 'Someone placid stays calm when things get stressful.', ARRAY['Her placid response frustrated those hoping to provoke a dispute.','Beyond the rapids, the river became placid again.'], ARRAY['calm','tranquil','serene'], ARRAY['agitated','turbulent'], 2, 3, 'From Latin placidus (gentle, quiet), related to placere (to please).', 'established', NULL, ARRAY[]::text[], NULL),
('equivocal', 'equivocal', 'ih-KWIV-uh-kul', 'adjective', 'Open to competing interpretations; not clearly expressing a position.', ARRAY[]::text[], 'An equivocal answer leaves you unsure what the speaker means.', ARRAY['The witness gave an equivocal account of the meeting.','The preliminary results were too equivocal to justify a policy change.'], ARRAY['ambiguous','unclear','noncommittal'], ARRAY['unequivocal','clear'], 2, 3, 'From Late Latin aequivocus, combining aequus (equal) and vox, vocis (voice), originally concerning a shared name with different meanings.', 'established', NULL, ARRAY[]::text[], NULL),
('equivocate', 'equivocate', 'ih-KWIV-uh-kayt', 'verb', 'To use ambiguous language to avoid committing to the truth.', ARRAY[]::text[], 'To equivocate is to dodge a clear answer through slippery wording.', ARRAY['The candidate continued to equivocate when asked whether she supported the bill.','Rather than equivocate, the researcher acknowledged the limits of the evidence.'], ARRAY['hedge','prevaricate','dodge'], ARRAY['avow','clarify'], 2, 3, 'From Medieval Latin aequivocare (to use ambiguous words), from Late Latin aequivocus (ambiguous).', 'established', NULL, ARRAY[]::text[], NULL),
('vociferous', 'vociferous', 'voh-SIF-er-us', 'adjective', 'Loud and forceful in expressing opinions or demands.', ARRAY[]::text[], 'Vociferous people make their objections impossible to ignore.', ARRAY['The proposal encountered vociferous opposition from local merchants.','A small but vociferous minority dominated the hearing.'], ARRAY['clamorous','loud','vehement'], ARRAY['quiet','restrained'], 2, 3, 'From Latin vociferari (to shout), combining vox, vocis (voice) and ferre (to carry), with an adjectival ending.', 'established', NULL, ARRAY[]::text[], NULL),
('agnostic', 'agnostic', 'ag-NOS-tik', 'adjective', 'Holding that a claim, especially about God, is unknown or unknowable.', ARRAY[]::text[], 'Being agnostic means not claiming certainty about the question.', ARRAY['The philosopher remained agnostic about the existence of a divine designer.','The committee was agnostic on which technical standard would prevail.'], ARRAY['uncommitted','undecided','noncommittal'], ARRAY['certain','convinced'], 2, 3, 'Coined by T. H. Huxley from Greek a- (not) and gnostos (known), with -ic.', 'established', NULL, ARRAY[]::text[], NULL),
('cognizant', 'cognizant', 'KOG-nih-zunt', 'adjective', 'Aware of or informed about something.', ARRAY[]::text[], 'Being cognizant of a problem means knowing it is there.', ARRAY['The board was cognizant of the proposal’s legal risks.','A careful editor remains cognizant of differences between dialects.'], ARRAY['aware','conscious','informed'], ARRAY['unaware','oblivious'], 2, 3, 'Formed in English on cognizance, through Anglo-French from Latin cognoscere (to learn or recognize).', 'established', NULL, ARRAY[]::text[], NULL),
('apathy', 'apathy', 'AP-uh-thee', 'noun', 'A lack of interest, concern, or emotional response.', ARRAY[]::text[], 'Apathy is not caring enough to react or get involved.', ARRAY['Voter apathy troubled the organizers more than open opposition.','The administration mistook exhausted silence for apathy.'], ARRAY['indifference','unconcern','listlessness'], ARRAY['enthusiasm','concern'], 2, 3, 'From Greek apatheia (freedom from suffering or emotion), from a- (without) and pathos (feeling or suffering).', 'established', NULL, ARRAY[]::text[], NULL),
('antipathy', 'antipathy', 'an-TIP-uh-thee', 'noun', 'A strong feeling of dislike or aversion.', ARRAY[]::text[], 'Antipathy is a strong dislike for someone or something.', ARRAY['His antipathy toward bureaucracy shaped every administrative decision.','The two scholars concealed their mutual antipathy during the debate.'], ARRAY['aversion','hostility','dislike'], ARRAY['sympathy','affinity'], 2, 3, 'From Greek antipatheia, from anti- (against) and pathos (feeling).', 'established', NULL, ARRAY[]::text[], NULL),
('empathy', 'empathy', 'EM-puh-thee', 'noun', 'The ability to understand or share another person’s feelings.', ARRAY[]::text[], 'Empathy helps you grasp what someone else is going through.', ARRAY['The novelist portrays even minor characters with empathy.','Empathy informed the interview technique without replacing critical judgment.'], ARRAY['understanding','fellow feeling','sensitivity'], ARRAY['callousness','indifference'], 2, 3, 'Formed from Greek empatheia (passion), from en- (in) and pathos (feeling), to render German Einfühlung in modern psychology.', 'established', NULL, ARRAY[]::text[], NULL),
('amorphous', 'amorphous', 'uh-MOR-fus', 'adjective', 'Lacking a definite shape, organization, or character.', ARRAY[]::text[], 'Something amorphous has no clear form or structure.', ARRAY['The committee transformed an amorphous proposal into a detailed plan.','An amorphous mass of debris blocked the entrance.'], ARRAY['shapeless','unstructured','undefined'], ARRAY['structured','definite'], 2, 3, 'From Greek amorphos (without form), from a- (without) and morphe (form), with English -ous.', 'established', NULL, ARRAY[]::text[], NULL),
('metamorphosis', 'metamorphosis', 'met-uh-MOR-fuh-sis', 'noun', 'A profound change in form or character.', ARRAY[]::text[], 'A metamorphosis is a major transformation, not a small adjustment.', ARRAY['The port’s metamorphosis into a financial center took a century.','The memoir records her intellectual metamorphosis during exile.'], ARRAY['transformation','conversion','transfiguration'], ARRAY[]::text[], 2, 3, 'From Greek metamorphosis (transformation), from metamorphoun (to transform), built on meta- (change) and morphe (form).', 'established', NULL, ARRAY[]::text[], NULL),
('anachronism', 'anachronism', 'uh-NAK-ruh-niz-um', 'noun', 'Something placed in or belonging to the wrong historical period.', ARRAY[]::text[], 'An anachronism is something that does not fit its historical time.', ARRAY['The wristwatch in the medieval scene is an obvious anachronism.','Critics considered the hereditary office an anachronism in a modern democracy.'], ARRAY['incongruity','misdating','archaism'], ARRAY[]::text[], 2, 3, 'From Greek anachronismos, from anachronizein (to refer to a wrong time), combining ana- and chronos (time).', 'established', NULL, ARRAY[]::text[], NULL),
('chronic', 'chronic', 'KRON-ik', 'adjective', 'Persisting for a long time or recurring repeatedly.', ARRAY[]::text[], 'A chronic problem keeps lasting or coming back.', ARRAY['Chronic underfunding weakened the agency’s ability to inspect factories.','The patient’s chronic pain required a long-term treatment plan.'], ARRAY['persistent','enduring','recurrent'], ARRAY['temporary','transient'], 2, 3, 'From Greek chronikos (of time), from chronos (time).', 'established', NULL, ARRAY[]::text[], NULL),
('philanthropist', 'philanthropist', 'fih-LAN-thruh-pist', 'noun', 'A person who promotes others’ welfare, especially through charitable giving.', ARRAY[]::text[], 'A philanthropist uses resources to help other people.', ARRAY['The philanthropist supported libraries rather than monuments bearing his name.','Several philanthropists funded independent research into neglected diseases.'], ARRAY['benefactor','humanitarian','donor'], ARRAY[]::text[], 2, 3, 'From philanthropy, ultimately Greek philanthropia (love of humankind), from philos (loving) and anthropos (human being).', 'established', NULL, ARRAY[]::text[], NULL),
('misanthrope', 'misanthrope', 'MIS-un-throhp', 'noun', 'A person who dislikes or distrusts humankind.', ARRAY[]::text[], 'A misanthrope has a low opinion of people in general.', ARRAY['The narrator presents himself as a misanthrope but repeatedly helps strangers.','Years of political betrayal turned the idealist into a misanthrope.'], ARRAY['cynic','people-hater'], ARRAY[]::text[], 2, 3, 'From Greek misanthropos (hating humankind), from misein (to hate) and anthropos (human being).', 'established', NULL, ARRAY[]::text[], NULL),
('diction', 'diction', 'DIK-shun', 'noun', 'A speaker’s or writer’s choice and use of words.', ARRAY['Clarity of spoken articulation.'], 'Diction is the kind of wording someone chooses.', ARRAY['The essay’s elevated diction contrasts with its ordinary subject.','Precise diction strengthened an otherwise tentative argument.'], ARRAY['wording','phrasing','expression'], ARRAY[]::text[], 2, 3, 'From Latin dictio (speaking, expression), from dicere (to say), with the stem dict-.', 'established', NULL, ARRAY[]::text[], NULL),
('edict', 'edict', 'EE-dikt', 'noun', 'An authoritative order or proclamation.', ARRAY[]::text[], 'An edict is an official command, not a suggestion.', ARRAY['The governor’s edict prohibited assemblies after sunset.','A royal edict could not erase generations of local custom.'], ARRAY['decree','order','proclamation'], ARRAY[]::text[], 2, 3, 'From Latin edictum (proclamation), from edicere (to proclaim), combining e- (out) and dicere (to say).', 'established', NULL, ARRAY[]::text[], NULL),
('malediction', 'malediction', 'mal-uh-DIK-shun', 'noun', 'A curse or expression wishing harm on someone.', ARRAY[]::text[], 'A malediction is a spoken wish that something bad happen.', ARRAY['The exile’s farewell was a malediction against the ruling family.','The inscription threatens a malediction against anyone who disturbs the tomb.'], ARRAY['curse','imprecation','execration'], ARRAY['blessing','benediction'], 3, 1, 'From Latin maledictio (evil speaking, curse), from male (ill) and dicere (to say).', 'established', NULL, ARRAY[]::text[], NULL),
('ambiguous', 'ambiguous', 'am-BIG-yoo-us', 'adjective', 'Having more than one plausible meaning or interpretation.', ARRAY[]::text[], 'Something ambiguous can reasonably be understood in different ways.', ARRAY['An ambiguous clause left the parties disputing who owned the patent.','The ending is deliberately ambiguous about the protagonist’s motives.'], ARRAY['equivocal','unclear','indeterminate'], ARRAY['unambiguous','explicit'], 2, 3, 'From Latin ambiguus (uncertain), from ambigere (to dispute or waver), combining ambi- (on both sides) and agere (to drive).', 'established', NULL, ARRAY[]::text[], NULL),
('ambivalent', 'ambivalent', 'am-BIV-uh-lunt', 'adjective', 'Having conflicting feelings about the same person, thing, or choice.', ARRAY[]::text[], 'You are ambivalent when part of you wants something and part does not.', ARRAY['She remained ambivalent about accepting a promotion that required relocation.','The novel takes an ambivalent view of technological progress.'], ARRAY['conflicted','torn','undecided'], ARRAY['resolute','wholehearted'], 2, 3, 'From German Ambivalenz, coined from Latin ambi- (both) and valentia (strength), from valere (to be strong).', 'established', NULL, ARRAY['ambiguous'], 'Ambivalent describes conflicting feelings; ambiguous describes multiple possible interpretations.'),
('anomaly', 'anomaly', 'uh-NOM-uh-lee', 'noun', 'Something that departs from an expected pattern or rule.', ARRAY[]::text[], 'An anomaly is something that does not fit the usual pattern.', ARRAY['The unexplained anomaly prompted the team to recalibrate its instruments.','Her rapid promotion was an anomaly in the rigid bureaucracy.'], ARRAY['irregularity','aberration','exception'], ARRAY['norm','regularity'], 2, 3, 'From Greek anomalia (unevenness), from anomalos (uneven), combining an- (not) and homalos (even).', 'established', NULL, ARRAY[]::text[], NULL),
('eulogy', 'eulogy', 'YOO-luh-jee', 'noun', 'A speech or piece of writing praising someone, especially after death.', ARRAY[]::text[], 'A eulogy honors someone by describing their admirable qualities.', ARRAY['Her eulogy celebrated the scientist’s generosity as well as his discoveries.','The anniversary essay reads more like a eulogy than a critical assessment.'], ARRAY['tribute','encomium','panegyric'], ARRAY['denunciation','condemnation'], 2, 3, 'From Greek eulogia (praise), from eu (well) and logos (speech).', 'established', NULL, ARRAY[]::text[], NULL),
('euphemism', 'euphemism', 'YOO-fuh-miz-um', 'noun', 'A mild or indirect expression replacing one considered harsh or offensive.', ARRAY[]::text[], 'A euphemism softens wording that might sound unpleasant.', ARRAY['The report used a euphemism to obscure the scale of the layoffs.','Calling the disaster an inconvenience was an insulting euphemism.'], ARRAY['softening','circumlocution','indirect expression'], ARRAY[]::text[], 2, 3, 'From Greek euphemismos, from euphemizein (to use favorable words), ultimately eu (well) and pheme (speech).', 'established', NULL, ARRAY[]::text[], NULL),
('cursory', 'cursory', 'KUR-suh-ree', 'adjective', 'Hasty and insufficiently thorough.', ARRAY[]::text[], 'A cursory look is too quick to catch much detail.', ARRAY['A cursory inspection failed to reveal the bridge’s structural damage.','He offered only a cursory summary of the opposing argument.'], ARRAY['superficial','perfunctory','hasty'], ARRAY['thorough','meticulous'], 2, 3, 'From Late Latin cursorius (of running), from Latin cursor (runner), from currere (to run).', 'established', NULL, ARRAY[]::text[], NULL),
('precursor', 'precursor', 'pree-KUR-ser', 'noun', 'Something that precedes and signals or helps produce a later development.', ARRAY[]::text[], 'A precursor comes before something and points toward its arrival.', ARRAY['The modest survey was a precursor to a nationwide study.','Early mechanical calculators were precursors of modern computers.'], ARRAY['forerunner','antecedent','harbinger'], ARRAY['successor'], 2, 3, 'From Latin praecursor (one who runs ahead), from prae- (before) and currere (to run).', 'established', NULL, ARRAY[]::text[], NULL),
('obsequious', 'obsequious', 'ub-SEE-kwee-us', 'adjective', 'Excessively submissive or eager to please someone powerful.', ARRAY[]::text[], 'An obsequious person tries far too hard to please the boss.', ARRAY['The minister surrounded himself with obsequious advisers.','Her obsequious flattery made the interview uncomfortable.'], ARRAY['servile','sycophantic','fawning'], ARRAY['defiant','assertive'], 3, 3, 'From Latin obsequiosus (compliant), from obsequium (compliance), from obsequi (to comply), combining ob- and sequi (to follow).', 'established', NULL, ARRAY[]::text[], NULL),
('fidelity', 'fidelity', 'fih-DEL-ih-tee', 'noun', 'Faithfulness to a person, commitment, or original source.', ARRAY[]::text[], 'Fidelity means staying true to someone or something.', ARRAY['The translator valued fidelity to tone as much as literal accuracy.','His fidelity to the movement survived years of disappointment.'], ARRAY['loyalty','faithfulness','accuracy'], ARRAY['disloyalty','infidelity'], 2, 3, 'Through French from Latin fidelitas (faithfulness), from fidelis (faithful), from fides (faith).', 'established', NULL, ARRAY[]::text[], NULL),
('diffident', 'diffident', 'DIF-ih-dunt', 'adjective', 'Lacking confidence and hesitant to assert oneself.', ARRAY[]::text[], 'Someone diffident is unsure of themselves and holds back.', ARRAY['The diffident student rarely volunteered her remarkably perceptive observations.','His diffident manner concealed substantial expertise.'], ARRAY['shy','self-doubting','hesitant'], ARRAY['confident','assertive'], 2, 3, 'From Latin diffidens, participle of diffidere (to distrust), combining dis- and fidere (to trust).', 'established', NULL, ARRAY[]::text[], NULL),
('perfidious', 'perfidious', 'per-FID-ee-us', 'adjective', 'Disloyal and willing to betray trust.', ARRAY[]::text[], 'A perfidious ally cannot be trusted to keep faith with you.', ARRAY['The general denounced the perfidious agreement that abandoned his troops.','A perfidious confidant sold the letters to a rival.'], ARRAY['treacherous','faithless','disloyal'], ARRAY['faithful','loyal'], 3, 3, 'From Latin perfidiosus (faithless), from perfidia (treachery), from perfidus, combining per- and fides (faith).', 'established', NULL, ARRAY[]::text[], NULL),
('lucid', 'lucid', 'LOO-sid', 'adjective', 'Clear and easy to understand.', ARRAY['Mentally clear and aware.'], 'A lucid explanation makes a difficult idea easy to follow.', ARRAY['Her lucid account made the statistical dispute accessible to nonexperts.','Despite his exhaustion, he remained lucid throughout the interview.'], ARRAY['clear','intelligible','coherent'], ARRAY['confused','obscure'], 2, 3, 'From Latin lucidus (bright, clear), from lucere (to shine).', 'established', NULL, ARRAY[]::text[], NULL),
('elucidate', 'elucidate', 'ih-LOO-sih-dayt', 'verb', 'To make something clear through explanation.', ARRAY[]::text[], 'To elucidate something is to explain it so it makes sense.', ARRAY['The diagrams elucidate relationships that the prose leaves obscure.','Further experiments may elucidate the mechanism behind the effect.'], ARRAY['clarify','explain','illuminate'], ARRAY['obscure','confuse'], 2, 3, 'From Late Latin elucidare (to make clear), from e- and Latin lucidus (clear), from lucere (to shine).', 'established', NULL, ARRAY[]::text[], NULL),
('pellucid', 'pellucid', 'puh-LOO-sid', 'adjective', 'Exceptionally clear in expression or transparent in appearance.', ARRAY[]::text[], 'Something pellucid is remarkably clear, whether water or writing.', ARRAY['Her pellucid prose conceals the difficulty of the underlying argument.','The expedition crossed a pellucid stream fed by mountain springs.'], ARRAY['transparent','lucid','limpid'], ARRAY['opaque','obscure'], 3, 3, 'From Latin pellucidus (transparent), from pellucere (to shine through), combining per- (through), assimilated to pel-, and lucere (to shine).', 'established', NULL, ARRAY[]::text[], NULL),
('pugnacious', 'pugnacious', 'pug-NAY-shus', 'adjective', 'Eager or quick to argue or fight.', ARRAY[]::text[], 'A pugnacious person is always ready for a confrontation.', ARRAY['The pugnacious columnist treated every disagreement as a personal challenge.','His pugnacious negotiating style alienated potential allies.'], ARRAY['combative','belligerent','quarrelsome'], ARRAY['peaceable','conciliatory'], 2, 3, 'From Latin pugnax, pugnacis (fond of fighting), from pugnare (to fight), with an English adjectival ending.', 'established', NULL, ARRAY[]::text[], NULL),
('impugn', 'impugn', 'im-PYOON', 'verb', 'To challenge the truth, validity, or integrity of something.', ARRAY[]::text[], 'To impugn a claim or person is to call their credibility into question.', ARRAY['The defense sought to impugn the witness’s reliability.','Questioning the method does not necessarily impugn the researcher’s motives.'], ARRAY['challenge','contest','dispute'], ARRAY['vindicate','uphold'], 2, 3, 'From Latin impugnare (to attack), combining in- (against) and pugnare (to fight); this in- is not the negative prefix.', 'established', NULL, ARRAY[]::text[], NULL),
('repugnant', 'repugnant', 'rih-PUG-nunt', 'adjective', 'Extremely offensive or objectionable.', ARRAY[]::text[], 'Something repugnant is deeply offensive to you.', ARRAY['The court found the practice repugnant to basic principles of justice.','She considered the proposed bargain morally repugnant.'], ARRAY['abhorrent','odious','repulsive'], ARRAY['appealing','agreeable'], 2, 3, 'From Latin repugnans, participle of repugnare (to fight back), combining re- (back) and pugnare (to fight).', 'established', NULL, ARRAY[]::text[], NULL),
('veracity', 'veracity', 'vuh-RAS-ih-tee', 'noun', 'Truthfulness or conformity to facts.', ARRAY[]::text[], 'Veracity is whether someone or something tells the truth.', ARRAY['Independent records confirmed the veracity of her account.','The committee questioned the witness’s veracity after repeated contradictions.'], ARRAY['truthfulness','accuracy','honesty'], ARRAY['falsehood','mendacity'], 2, 3, 'From Medieval Latin veracitas, from Latin verax (truthful), from verus (true).', 'established', NULL, ARRAY[]::text[], NULL),
('verisimilitude', 'verisimilitude', 'ver-ih-sih-MIL-ih-tood', 'noun', 'The appearance of being true or realistically plausible.', ARRAY[]::text[], 'Verisimilitude makes an invented account feel convincingly real.', ARRAY['Small domestic details give the historical novel remarkable verisimilitude.','The forgery achieved verisimilitude without reproducing the artist’s technique.'], ARRAY['plausibility','realism','lifelikeness'], ARRAY['implausibility'], 3, 3, 'From Latin verisimilitudo (likeness to truth), from verisimilis, combining veri (of the true) and similis (like).', 'established', NULL, ARRAY[]::text[], NULL),
('tacit', 'tacit', 'TAS-it', 'adjective', 'Understood or implied without being explicitly stated.', ARRAY[]::text[], 'A tacit agreement is understood even though nobody says it aloud.', ARRAY['Their silence was interpreted as tacit approval.','The partners had a tacit understanding not to discuss their earlier dispute.'], ARRAY['implicit','unspoken','implied'], ARRAY['explicit','expressed'], 2, 3, 'From Latin tacitus (silent), the past participle of tacere (to be silent).', 'established', NULL, ARRAY[]::text[], NULL),
('taciturn', 'taciturn', 'TAS-ih-turn', 'adjective', 'Habitually speaking little.', ARRAY[]::text[], 'A taciturn person generally does not say much.', ARRAY['The taciturn engineer preferred diagrams to lengthy presentations.','His taciturn disposition was mistaken for hostility.'], ARRAY['reserved','quiet','uncommunicative'], ARRAY['loquacious','garrulous'], 2, 3, 'From Latin taciturnus (inclined to silence), from tacitus (silent), from tacere.', 'established', NULL, ARRAY[]::text[], NULL),
('reticent', 'reticent', 'RET-ih-sunt', 'adjective', 'Reserved about expressing one’s thoughts or feelings.', ARRAY[]::text[], 'Someone reticent keeps their thoughts or personal details to themselves.', ARRAY['The witness was reticent about the negotiations preceding the sale.','Normally reticent, she spoke openly about the project’s failures.'], ARRAY['reserved','restrained','uncommunicative'], ARRAY['forthcoming','voluble'], 2, 3, 'From Latin reticens, participle of reticere (to keep silent), from re- and tacere (to be silent), with a vowel change.', 'established', NULL, ARRAY[]::text[], NULL),
('gregarious', 'gregarious', 'grih-GAIR-ee-us', 'adjective', 'Sociable and fond of other people’s company.', ARRAY[]::text[], 'A gregarious person enjoys being around others.', ARRAY['Her gregarious temperament made solitary fieldwork difficult.','The gregarious host introduced guests who shared obscure interests.'], ARRAY['sociable','outgoing','convivial'], ARRAY['reclusive','unsociable'], 2, 3, 'From Latin gregarius (belonging to a flock), from grex, gregis (flock).', 'established', NULL, ARRAY[]::text[], NULL),
('egregious', 'egregious', 'ih-GREE-jus', 'adjective', 'Outstandingly bad or shocking.', ARRAY[]::text[], 'Something egregious is so bad that it stands out.', ARRAY['The audit uncovered an egregious misuse of public funds.','An egregious factual error undermined the entire review.'], ARRAY['flagrant','glaring','outrageous'], ARRAY['minor','slight'], 2, 3, 'From Latin egregius (distinguished), literally out of the flock, from e- (out) and grex, gregis (flock). English shifted from exceptional merit to conspicuous badness.', 'established', NULL, ARRAY[]::text[], NULL),
('aggregate', 'aggregate', 'AG-ruh-gayt', 'verb', 'To collect or combine into a whole.', ARRAY['A combined whole, when used as a noun.'], 'To aggregate things is to bring them together into a total or group.', ARRAY['The researchers aggregate responses before publishing the results.','Small errors can aggregate into a substantial discrepancy.'], ARRAY['combine','collect','assemble'], ARRAY['disperse','separate'], 2, 3, 'From Latin aggregatus, participle of aggregare (to add to a flock), from ad- (to) and grex, gregis (flock).', 'established', NULL, ARRAY[]::text[], NULL),
('laconic', 'laconic', 'luh-KON-ik', 'adjective', 'Using very few words.', ARRAY[]::text[], 'A laconic reply gets its point across in very few words.', ARRAY['His laconic testimony left little room for speculation.','The chair’s laconic dismissal ended the debate.'], ARRAY['terse','concise','succinct'], ARRAY['verbose','wordy'], 2, 3, 'From Greek Lakonikos (Spartan), from Lakonia, the region of Sparta, whose inhabitants were reputedly terse.', 'established', NULL, ARRAY[]::text[], NULL),
('quixotic', 'quixotic', 'kwik-SOT-ik', 'adjective', 'Impractically idealistic or romantically unrealistic.', ARRAY[]::text[], 'A quixotic plan is noble or exciting but unlikely to work.', ARRAY['Her quixotic campaign sought to abolish all commercial advertising.','The donor admired the project’s quixotic ambition despite its obvious risks.'], ARRAY['idealistic','impractical','visionary'], ARRAY['pragmatic','realistic'], 2, 3, 'From Don Quixote, the idealistic protagonist of Cervantes’s novel, with -ic.', 'established', NULL, ARRAY[]::text[], NULL),
('ubiquitous', 'ubiquitous', 'yoo-BIK-wih-tus', 'adjective', 'Present or found everywhere.', ARRAY[]::text[], 'Something ubiquitous seems to turn up wherever you look.', ARRAY['Digital surveillance has become ubiquitous in major cities.','The once ubiquitous plant is now rare in this valley.'], ARRAY['omnipresent','pervasive','universal'], ARRAY['rare','scarce'], 2, 3, 'From Latin ubique (everywhere), ultimately ubi (where) and an element meaning each or every, with an adjectival ending.', 'established', NULL, ARRAY[]::text[], NULL),
('ephemeral', 'ephemeral', 'ih-FEM-er-ul', 'adjective', 'Lasting only a short time.', ARRAY[]::text[], 'Something ephemeral disappears or ends quickly.', ARRAY['The exhibition examines the ephemeral fame produced by viral media.','Their alliance proved ephemeral once the immediate threat receded.'], ARRAY['fleeting','transient','short-lived'], ARRAY['lasting','enduring'], 2, 3, 'From Greek ephemeros (lasting a day), from epi- and hemera (day).', 'established', NULL, ARRAY[]::text[], NULL),
('enervate', 'enervate', 'EN-er-vayt', 'verb', 'To weaken or drain of energy.', ARRAY[]::text[], 'To enervate someone is to leave them weaker, not more energetic.', ARRAY['The prolonged heat enervated even the most experienced hikers.','Repeated procedural delays enervated the reform movement.'], ARRAY['weaken','exhaust','debilitate'], ARRAY['energize','invigorate'], 2, 3, 'From Latin enervare (to weaken), from e- (out) and nervus (sinew, strength).', 'established', NULL, ARRAY['energize'], 'Enervate means weaken, whereas energize means give energy.'),
('prodigal', 'prodigal', 'PROD-ih-gul', 'adjective', 'Wastefully extravagant with money or resources.', ARRAY[]::text[], 'A prodigal spender uses far more than they can sensibly afford.', ARRAY['The heir’s prodigal spending depleted the estate within a decade.','A prodigal use of water threatened the town’s reserves.'], ARRAY['extravagant','wasteful','profligate'], ARRAY['frugal','thrifty'], 2, 3, 'From Latin prodigus (lavish), from prodigere (to drive forth or squander), combining prod- and agere (to drive).', 'established', NULL, ARRAY[]::text[], NULL),
('venerate', 'venerate', 'VEN-uh-rayt', 'verb', 'To regard with deep respect or reverence.', ARRAY[]::text[], 'To venerate someone is to honor them with profound respect.', ARRAY['Later generations venerated the judge for defending judicial independence.','The community venerates the grove as a sacred place.'], ARRAY['revere','honor','esteem'], ARRAY['despise','scorn'], 2, 3, 'From Latin veneratus, participle of venerari (to worship or revere).', 'established', NULL, ARRAY[]::text[], NULL),
('capricious', 'capricious', 'kuh-PRISH-us', 'adjective', 'Changing unpredictably according to passing whims.', ARRAY[]::text[], 'A capricious person changes their mind for no reliable reason.', ARRAY['Investors feared the ruler’s capricious interventions in the market.','Capricious grading made the course unusually stressful.'], ARRAY['fickle','unpredictable','whimsical'], ARRAY['consistent','steady'], 2, 3, 'Through French from Italian capriccioso, from capriccio (whim). The deeper origin of capriccio is debated; a simple goat-based derivation is not secure.', 'uncertain', NULL, ARRAY[]::text[], NULL),
('mitigate', 'mitigate', 'MIT-ih-gayt', 'verb', 'To make something harmful or severe less serious.', ARRAY[]::text[], 'To mitigate a problem is to reduce its damage or severity.', ARRAY['Wetlands can mitigate the effects of coastal flooding.','The apology mitigated public anger without restoring trust.'], ARRAY['alleviate','lessen','moderate'], ARRAY['aggravate','exacerbate'], 2, 3, 'From Latin mitigatus, participle of mitigare (to soften), from mitis (mild) and agere (to make or do).', 'established', NULL, ARRAY[]::text[], NULL),
('obdurate', 'obdurate', 'OB-duh-rut', 'adjective', 'Stubbornly refusing to change one’s attitude or position.', ARRAY[]::text[], 'An obdurate person will not budge even when there is good reason.', ARRAY['The minister remained obdurate despite overwhelming evidence against the policy.','Negotiators confronted an obdurate refusal to compromise.'], ARRAY['unyielding','stubborn','intransigent'], ARRAY['yielding','flexible'], 2, 3, 'From Latin obduratus, participle of obdurare (to harden), from ob- and durare (to harden), from durus (hard).', 'established', NULL, ARRAY[]::text[], NULL),
('prevaricate', 'prevaricate', 'prih-VAIR-ih-kayt', 'verb', 'To evade the truth through misleading or evasive statements.', ARRAY[]::text[], 'To prevaricate is to avoid telling the truth straightforwardly.', ARRAY['The official prevaricated when asked who authorized the payment.','Witnesses who prevaricate can undermine an otherwise sound defense.'], ARRAY['equivocate','evade','dissemble'], ARRAY['confess','avow'], 2, 3, 'From Latin praevaricari (to straddle or act collusively), from prae- and varicare (to straddle), related to varus (bent).', 'established', NULL, ARRAY[]::text[], NULL),
('garrulous', 'garrulous', 'GAIR-uh-lus', 'adjective', 'Excessively talkative, especially about trivial matters.', ARRAY[]::text[], 'A garrulous person keeps talking, often without saying much that matters.', ARRAY['The garrulous passenger narrated every stage of his journey.','Her garrulous recollections nevertheless preserved valuable historical details.'], ARRAY['loquacious','verbose','talkative'], ARRAY['taciturn','terse'], 2, 3, 'From Latin garrulus (chattering), from garrire (to chatter).', 'established', NULL, ARRAY[]::text[], NULL),
('pedantic', 'pedantic', 'puh-DAN-tik', 'adjective', 'Excessively concerned with minor rules, details, or displays of learning.', ARRAY[]::text[], 'Someone pedantic focuses on tiny technical points more than the main idea.', ARRAY['His pedantic corrections distracted from the substance of the argument.','The review was learned without becoming pedantic.'], ARRAY['nitpicking','hairsplitting','bookish'], ARRAY['unpretentious'], 2, 3, 'From pedant, through French from Italian pedante (teacher); the deeper origin of the Italian word is uncertain.', 'uncertain', NULL, ARRAY[]::text[], NULL),
('esoteric', 'esoteric', 'es-uh-TAIR-ik', 'adjective', 'Understood by or intended for a small group with specialized knowledge.', ARRAY[]::text[], 'Something esoteric makes sense mainly to insiders with special knowledge.', ARRAY['The dispute concerned an esoteric point of medieval law.','Her lecture made an esoteric discipline accessible to new students.'], ARRAY['specialized','arcane','abstruse'], ARRAY['accessible','commonplace'], 2, 3, 'From Greek esoterikos (inner), from esotero (further within), related to eso (within).', 'established', NULL, ARRAY[]::text[], NULL),
('ostentatious', 'ostentatious', 'os-ten-TAY-shus', 'adjective', 'Designed to attract admiration through conspicuous display.', ARRAY[]::text[], 'Something ostentatious shows off in a way people are meant to notice.', ARRAY['The mansion’s ostentatious entrance contrasted with the owner’s professed modesty.','She avoided ostentatious gestures of generosity.'], ARRAY['showy','pretentious','flamboyant'], ARRAY['modest','understated'], 2, 3, 'From ostentation, ultimately Latin ostentatio (display), from ostentare (to display repeatedly), from ostendere (to show).', 'established', NULL, ARRAY[]::text[], NULL),
('intransigent', 'intransigent', 'in-TRAN-sih-junt', 'adjective', 'Unwilling to compromise or change a position.', ARRAY[]::text[], 'An intransigent person refuses to meet anyone halfway.', ARRAY['Both factions remained intransigent throughout the negotiations.','The union softened its initially intransigent stance.'], ARRAY['uncompromising','inflexible','obdurate'], ARRAY['flexible','conciliatory'], 2, 3, 'Through French from Spanish intransigente, from in- (not) and transigente, from transigir (to compromise), ultimately Latin transigere.', 'established', NULL, ARRAY[]::text[], NULL),
('sanguine', 'sanguine', 'SANG-gwin', 'adjective', 'Optimistic or confidently hopeful, especially despite difficulty.', ARRAY['Blood-red in color.'], 'Someone sanguine expects things to work out well.', ARRAY['Analysts remained sanguine despite the disappointing first-quarter figures.','She was less sanguine about the prospects for a quick settlement.'], ARRAY['optimistic','hopeful','confident'], ARRAY['pessimistic','despondent'], 2, 3, 'From Latin sanguineus (of blood), from sanguis (blood). The optimistic sense reflects the historical association of a blood-dominant temperament with cheerfulness.', 'established', NULL, ARRAY[]::text[], NULL),
('laud', 'laud', 'LAWD', 'verb', 'To praise highly.', ARRAY[]::text[], 'To laud someone is to praise them enthusiastically.', ARRAY['The panel lauded the study’s methodological rigor.','Critics lauded the performance but questioned the production’s extravagant cost.'], ARRAY['praise','acclaim','extol'], ARRAY['censure','condemn'], 2, 3, 'From Latin laudare (to praise), from laus, laudis (praise).', 'established', NULL, ARRAY[]::text[], NULL),
('belie', 'belie', 'bih-LYE', 'verb', 'To give a false impression of or contradict.', ARRAY[]::text[], 'Something can belie appearances by being different from what they suggest.', ARRAY['Her relaxed manner belied the urgency of her mission.','The figures belie the claim that demand has remained stable.'], ARRAY['contradict','misrepresent','disprove'], ARRAY['confirm','substantiate'], 2, 3, 'From Old English beleogan (to deceive by lying), combining be- and leogan (to lie).', 'established', NULL, ARRAY[]::text[], NULL),
('exacerbate', 'exacerbate', 'ig-ZAS-er-bayt', 'verb', 'To make a problem or unpleasant condition worse.', ARRAY[]::text[], 'To exacerbate a problem is to make it worse.', ARRAY['Poor communication exacerbated tensions between the departments.','The drought exacerbated existing inequalities in access to water.'], ARRAY['aggravate','worsen','intensify'], ARRAY['mitigate','alleviate'], 2, 3, 'From Latin exacerbatus, participle of exacerbare (to irritate), from ex- and acerbus (harsh or bitter).', 'established', NULL, ARRAY[]::text[], NULL),
('dogmatic', 'dogmatic', 'dawg-MAT-ik', 'adjective', 'Asserting opinions as unquestionable truths.', ARRAY[]::text[], 'A dogmatic person treats their views as beyond debate.', ARRAY['His dogmatic insistence on one method discouraged useful experimentation.','The essay is forceful without becoming dogmatic.'], ARRAY['doctrinaire','rigid','opinionated'], ARRAY['open-minded','flexible'], 2, 3, 'From Greek dogmatikos, from dogma, dogmatos (opinion or decree), related to dokein (to seem or think).', 'established', NULL, ARRAY[]::text[], NULL),
('hackneyed', 'hackneyed', 'HAK-need', 'adjective', 'Overused and therefore lacking freshness or force.', ARRAY[]::text[], 'A hackneyed phrase has been used so often that it feels stale.', ARRAY['The speech relied on hackneyed metaphors about journeys and bridges.','Even a hackneyed plot can succeed through unusually vivid characterization.'], ARRAY['trite','stale','clichéd'], ARRAY['original','fresh'], 2, 3, 'From hackney (to use routinely or hire out), from the noun for a hired horse, associated with the place-name Hackney.', 'established', NULL, ARRAY[]::text[], NULL),
('vacillate', 'vacillate', 'VAS-uh-layt', 'verb', 'To waver between choices or opinions.', ARRAY[]::text[], 'To vacillate is to keep switching between options.', ARRAY['The council vacillated between renovation and complete replacement.','Investors vacillate when reliable information is scarce.'], ARRAY['waver','hesitate','oscillate'], ARRAY['resolve','decide'], 2, 3, 'From Latin vacillatus, participle of vacillare (to sway or waver).', 'established', NULL, ARRAY[]::text[], NULL),
('zealous', 'zealous', 'ZEL-us', 'adjective', 'Intensely enthusiastic and dedicated to a cause or task.', ARRAY[]::text[], 'A zealous supporter cares deeply and works hard for the cause.', ARRAY['Zealous volunteers canvassed every district before the election.','A zealous pursuit of efficiency can neglect other institutional values.'], ARRAY['fervent','ardent','devoted'], ARRAY['apathetic','indifferent'], 2, 3, 'From zeal, through Latin zelus from Greek zelos (eager rivalry or ardor), with English -ous.', 'established', NULL, ARRAY[]::text[], NULL),
('prosaic', 'prosaic', 'proh-ZAY-ik', 'adjective', 'Ordinary and unimaginative rather than interesting or poetic.', ARRAY[]::text[], 'Something prosaic is plain and everyday, not exciting.', ARRAY['The mystery had a prosaic explanation: a mislabeled storage box.','Financial constraints forced a prosaic alternative to the architect’s dramatic design.'], ARRAY['mundane','humdrum','unimaginative'], ARRAY['imaginative','extraordinary'], 2, 3, 'From Latin prosaicus (in prose), from prosa (prose), originally prosa oratio (straightforward speech).', 'established', NULL, ARRAY[]::text[], NULL),
('recondite', 'recondite', 'REK-un-dyte', 'adjective', 'Little known and difficult to understand.', ARRAY[]::text[], 'Something recondite is obscure enough to puzzle most people.', ARRAY['The footnotes pursue recondite disputes irrelevant to the central thesis.','Her expertise extended to the most recondite corners of tax law.'], ARRAY['obscure','abstruse','arcane'], ARRAY['accessible','familiar'], 3, 3, 'From Latin reconditus (hidden away), participle of recondere (to store away), from re- and condere (to put together or store).', 'established', NULL, ARRAY[]::text[], NULL),
('austere', 'austere', 'aw-STEER', 'adjective', 'Severely plain or strict in manner and habits.', ARRAY[]::text[], 'Something austere avoids comfort, decoration, or indulgence.', ARRAY['The austere chamber contained only a desk and two chairs.','His austere upbringing discouraged any public display of emotion.'], ARRAY['severe','spartan','plain'], ARRAY['luxurious','indulgent'], 2, 3, 'Through French and Latin from Greek austeros (harsh or severe), originally associated with a dry or bitter taste.', 'established', NULL, ARRAY[]::text[], NULL),
('candid', 'candid', 'KAN-did', 'adjective', 'Honest and direct, even about uncomfortable matters.', ARRAY['Unposed or unarranged, especially of a photograph.'], 'A candid person tells you frankly what they think.', ARRAY['The consultant offered a candid assessment of the project’s weaknesses.','Their candid discussion repaired months of misunderstanding.'], ARRAY['frank','forthright','sincere'], ARRAY['evasive','disingenuous'], 2, 3, 'From Latin candidus (white, bright, or sincere), from candere (to shine).', 'established', NULL, ARRAY[]::text[], NULL),
('censure', 'censure', 'SEN-sher', 'verb', 'To express strong, formal disapproval of someone or something.', ARRAY[]::text[], 'To censure someone is to criticize their conduct officially or strongly.', ARRAY['The assembly voted to censure the minister for concealing the report.','The review censured the company’s disregard for worker safety.'], ARRAY['condemn','reprimand','rebuke'], ARRAY['praise','laud'], 2, 3, 'From Latin censura (judgment), from censere (to assess or judge).', 'established', NULL, ARRAY['censor'], 'Censure means condemn; censor means suppress or remove objectionable material.'),
('deference', 'deference', 'DEF-er-uns', 'noun', 'Respectful submission to another person’s judgment or wishes.', ARRAY[]::text[], 'Showing deference means respectfully letting someone else’s judgment take priority.', ARRAY['Out of deference to local custom, the visitors postponed the ceremony.','Excessive deference to seniority discouraged younger researchers from challenging errors.'], ARRAY['respect','submission','regard'], ARRAY['defiance','disrespect'], 2, 3, 'From French déférence, related to déférer (to yield), ultimately Latin deferre (to carry down or offer).', 'established', NULL, ARRAY[]::text[], NULL),
('disparage', 'disparage', 'dih-SPAIR-ij', 'verb', 'To speak of as inferior or unworthy.', ARRAY[]::text[], 'To disparage something is to talk about it dismissively.', ARRAY['The critic disparaged the novel without addressing its central argument.','Managers should not disparage employees who identify genuine risks.'], ARRAY['belittle','denigrate','decry'], ARRAY['praise','extol'], 2, 3, 'From Old French desparagier (to marry below one’s rank or degrade), from des- and parage (lineage or rank).', 'established', NULL, ARRAY[]::text[], NULL);
